/**
 * Looks up the unique mood board combination for the 3 selected tiles.
 * Order of selected tiles doesn't matter.
 */
export function getMoodBoardCombo(selectedTiles: string[]): MoodBoardCombo | undefined {
  if (selectedTiles.length !== 3) return undefined;
  const sortedSelection = [...selectedTiles].sort();
  return MOOD_BOARD_COMBINATIONS.find(combo => {
    const sortedComboTiles = [...combo.tiles].sort();
    return sortedComboTiles[0] === sortedSelection[0] &&
           sortedComboTiles[1] === sortedSelection[1] &&
           sortedComboTiles[2] === sortedSelection[2];
  });
}
